class Solution {
    public int hammingDistance(int x, int y) {
        int d = x ^ y;
        int cnt = 0;
        for (int b = 0; b < 32; b++) {
            if (((d >> b) & 1) == 1) cnt++;
        }
        return cnt;
    }
}

class Solution {
    public int hammingDistance(int x, int y) {
        int d = x ^ y;
        int cnt = 0;
        while (d != 0) {
            cnt += d % 2;
            d /= 2;
        }
        return cnt;
    }
}

class Solution {
    public int hammingDistance(int x, int y) {
        int d = x ^ y;
        int cnt = 0;
        while (d != 0) {
            d &= (d - 1);
            cnt++;
        }
        return cnt;
    }
}
